import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"招魂","description":"","frontmatter":{"title":"招魂","date":"2026-11-24T00:00:00.000Z","seq":27,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"宋玉","source_book":"楚辞","prev":{"text":"九辩","link":"/blogs/楚辞/九辩.html"},"next":{"text":"大招","link":"/blogs/楚辞/大招.html"}},"headers":[],"relativePath":"blogs/楚辞/招魂.md","filePath":"blogs/楚辞/招魂.md"}'),o={name:"blogs/楚辞/招魂.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="招魂" tabindex="-1">招魂 <a class="header-anchor" href="#招魂" aria-label="Permalink to &quot;招魂&quot;">​</a></h1><p class="poem-meta">先秦 · 宋玉　·　招魂</p><div class="poem"><p class="poem-stanza">朕幼清以廉洁兮，身服义而未沫。</p><p class="poem-stanza">主此盛德兮，牵于俗而芜秽。</p><p class="poem-stanza">上无所考此盛德兮，长离殃而愁苦。</p><p class="poem-stanza">帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”</p><p class="poem-stanza">巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”</p><p class="poem-stanza">巫阳焉乃下招曰：魂兮归来！去君之恒干，何为四方些？</p><p class="poem-stanza">舍君之乐处，而离彼不祥些！魂兮归来！东方不可以讬些。</p><p class="poem-stanza">长人千仞，惟魂是索些。</p><p class="poem-stanza">十日代出，流金铄石些。</p><p class="poem-stanza">彼皆习之，魂往必释些。</p><p class="poem-stanza">归来兮！不可以讬些。</p><p class="poem-stanza">魂兮归来！南方不可以止些。</p><p class="poem-stanza">雕题黑齿，得人肉以祀，以其骨为醢些。</p><p class="poem-stanza">蝮蛇蓁蓁，封狐千里些。</p><p class="poem-stanza">雄虺九首，往来倏忽，吞人以益其心些。</p><p class="poem-stanza">归来兮！不可久淫些。</p><p class="poem-stanza">魂兮归来！西方之害，流沙千里些。</p><p class="poem-stanza">旋入雷渊，爢散而不可止些。</p><p class="poem-stanza">幸而得脱，其外旷宇些。</p><p class="poem-stanza">赤蚁若象，玄蜂若壶些。</p><p class="poem-stanza">五谷不生，丛菅是食些。</p><p class="poem-stanza">其土烂人，求水无所得些。</p><p class="poem-stanza">彷徉无所倚，广大无所极些。</p><p class="poem-stanza">归来兮！恐自遗贼些。</p><p class="poem-stanza">魂兮归来！北方不可以止些。</p><p class="poem-stanza">增冰峨峨，飞雪千里些。</p><p class="poem-stanza">归来兮！不可以久些。</p><p class="poem-stanza">魂兮归来！君无上天些。</p><p class="poem-stanza">虎豹九关，啄害下人些。</p><p class="poem-stanza">一夫九首，拔木九千些。</p><p class="poem-stanza">豺狼从目，往来侁侁些。</p><p class="poem-stanza">悬人以嬉，投之深渊些。</p><p class="poem-stanza">致命于帝，然后得瞑些。</p><p class="poem-stanza">归来！往恐危身些。</p><p class="poem-stanza">魂兮归来！君无下此幽都些。</p><p class="poem-stanza">土伯九约，其角觺觺些。</p><p class="poem-stanza">敦脄血拇，逐人伂駓駓些。</p><p class="poem-stanza">参目虎首，其身若牛些。</p><p class="poem-stanza">此皆甘人，归来！恐自遗灾些。</p><p class="poem-stanza">魂兮归来！入修门些。</p><p class="poem-stanza">工祝招君，背行先些。</p><p class="poem-stanza">秦篝齐缕，郑绵络些。</p><p class="poem-stanza">招具该备，永啸呼些。</p><p class="poem-stanza">魂兮归来！反故居些。</p><p class="poem-stanza">天地四方，多贼奸些。</p><p class="poem-stanza">像设君室，静闲安些。</p><p class="poem-stanza">高堂邃宇，槛层轩些。</p><p class="poem-stanza">层台累榭，临高山些。</p><p class="poem-stanza">网户朱缀，刻方连些。</p><p class="poem-stanza">冬有穾厦，夏室寒些。</p><p class="poem-stanza">川谷径复，流潺湲些。</p><p class="poem-stanza">光风转蕙，氾崇兰些。</p><p class="poem-stanza">经堂入奥，朱尘筵些。</p><p class="poem-stanza">砥室翠翘，挂曲琼些。</p><p class="poem-stanza">翡翠珠被，烂齐光些。</p><p class="poem-stanza">蒻阿拂壁，罗帱张些。</p><p class="poem-stanza">纂组绮缟，结琦璜些。</p><p class="poem-stanza">室中之观，多珍怪些。</p><p class="poem-stanza">兰膏明烛，华容备些。</p><p class="poem-stanza">二八侍宿，射递代些。</p><p class="poem-stanza">九侯淑女，多迅众些。</p><p class="poem-stanza">盛鬋不同制，实满宫些。</p><p class="poem-stanza">容态好比，顺弥代些。</p><p class="poem-stanza">弱颜固植，謇其有意些。</p><p class="poem-stanza">姱容修态，絚洞房些。</p><p class="poem-stanza">蛾眉曼睩，目腾光些。</p><p class="poem-stanza">靡颜腻理，遗视矊些。</p><p class="poem-stanza">离榭修幕，侍君之闲些。</p><p class="poem-stanza">悲帷翠帐，饰高堂些。</p><p class="poem-stanza">红壁沙版，玄玉梁些。</p><p class="poem-stanza">仰观刻桷，画龙蛇些。</p><p class="poem-stanza">坐堂伏槛，临曲池些。</p><p class="poem-stanza">芙蓉始发，杂芰荷些。</p><p class="poem-stanza">紫茎屏风，文缘波些。</p><p class="poem-stanza">文异豹饰，侍陂陁些。</p><p class="poem-stanza">轩辌既低，步骑罗些。</p><p class="poem-stanza">兰薄户树，琼木篱些。</p><p class="poem-stanza">魂兮归来！何远为些？</p><p class="poem-stanza">室家遂宗，食多方些。</p><p class="poem-stanza">稻粢穱麦，挐黄梁些。</p><p class="poem-stanza">大苦醎酸，辛甘行些。</p><p class="poem-stanza">肥牛之腱，臑若芳些。</p><p class="poem-stanza">和酸若苦，陈吴羹些。</p><p class="poem-stanza">胹鳖炮羔，有柘浆些。</p><p class="poem-stanza">鹄酸臇凫，煎鸿鸧些。</p><p class="poem-stanza">露鸡臛蠵，厉而不爽些。</p><p class="poem-stanza">粔籹蜜饵，有餦餭些。</p><p class="poem-stanza">瑶浆蜜勺，实羽觞些。</p><p class="poem-stanza">挫糟冻饮，酎清凉些。</p><p class="poem-stanza">华酌既陈，有琼浆些。</p><p class="poem-stanza">归来反故室，敬而无妨些。</p><p class="poem-stanza">肴羞未通，女乐罗些。</p><p class="poem-stanza">敶钟按鼓，造新歌些。</p><p class="poem-stanza">《涉江》《采菱》，发《扬荷》些。</p><p class="poem-stanza">美人既醉，朱颜酡些。</p><p class="poem-stanza">嬉光眇视，目曾波些。</p><p class="poem-stanza">被文服纤，丽而不奇些。</p><p class="poem-stanza">长发曼鬋，艳陆离些。</p><p class="poem-stanza">二八齐容，起郑舞些。</p><p class="poem-stanza">衽若交竿，抚案下些。</p><p class="poem-stanza">竽瑟狂会，搷鸣鼓些。</p><p class="poem-stanza">宫庭震惊，发&lt;激楚&gt;些。</p><p class="poem-stanza">吴歈蔡讴，奏大吕些。</p><p class="poem-stanza">士女杂坐，乱而不分些。</p><p class="poem-stanza">放敶组缨，班其相纷些。</p><p class="poem-stanza">郑卫妖玩，来杂陈些。</p><p class="poem-stanza">《激楚》之结，独秀先些。</p><p class="poem-stanza">菎蔽象棋，有六簙些。</p><p class="poem-stanza">分曹并进，遒相迫些。</p><p class="poem-stanza">成枭而牟，呼五白些。</p><p class="poem-stanza">晋制犀比，费白日些。</p><p class="poem-stanza">铿钟摇簴，揳梓瑟些。</p><p class="poem-stanza">娱酒不废，沈日夜些。</p><p class="poem-stanza">兰膏明烛，华灯错些。</p><p class="poem-stanza">结撰至思，兰芳假些。</p><p class="poem-stanza">人有所极，同心赋些。</p><p class="poem-stanza">酎饮尽欢，乐先故些。</p><p class="poem-stanza">魂兮归来！反故居些。</p><p class="poem-stanza">乱曰：献岁发春兮，汨吾南征。</p><p class="poem-stanza">菉蘋齐叶兮，白芷生。</p><p class="poem-stanza">路贯庐江兮，左长薄。</p><p class="poem-stanza">倚沼畦瀛兮，遥望博。</p><p class="poem-stanza">青骊结驷兮，齐千乘。</p><p class="poem-stanza">悬火延起兮，玄颜烝。</p><p class="poem-stanza">步及骤处兮，诱骋先。</p><p class="poem-stanza">抑骛若通兮，引车右还。</p><p class="poem-stanza">与王趋梦兮，课后先。</p><p class="poem-stanza">君王亲发兮，惮青兕。</p><p class="poem-stanza">朱明承夜兮，时不可以淹。</p><p class="poem-stanza">皋兰被径兮，斯路渐。</p><p class="poem-stanza">湛湛江水兮，上有枫。</p><p class="poem-stanza">目极千里兮，伤春心。</p><p class="poem-stanza">魂兮归来，哀江南！</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
